export function getLessonIllustration(unitId: number, lessonId: number, fallback?: string): string {
  const key = `u${unitId}_l${lessonId}`;

  // Priority 1: Dedicated flagship Nano Banana illustration if available
  if (NANO_BANANA_IMAGES[key]) {
    return NANO_BANANA_IMAGES[key];
  }

  // Priority 2: Explicit local image fallback (.jpg, .png, .svg)
  if (fallback && (fallback.startsWith("/illustrations/") || fallback.startsWith("data:image/svg"))) {
    return fallback;
  }

  // Priority 3: Dedicated 2D vector illustration (instant 0ms, crisp on any screen)
  if (LESSON_ILLUSTRATIONS[key]) {
    return LESSON_ILLUSTRATIONS[key];
  }

  // Priority 4: Unit fallback
  if (UNIT_IMAGES[unitId]) {
    return UNIT_IMAGES[unitId];
  }

  return "/illustrations/lessons/u1_l1.jpg";
}
